class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def distributeCandy(root):
    if not root:
        return 0

    def dfs(node):
        if not node:
            return 0
        left = dfs(node.left)
        right = dfs(node.right)
        total = node.val + left + right
        node.val = 1
        return total

    total_candies = dfs(root)
    moves = 0

    def calculate_moves(node):
        nonlocal moves
        if not node:
            return
        if node.left:
            moves += abs(node.left.val - 1)
            node.left.val = 1
        if node.right:
            moves += abs(node.right.val - 1)
            node.right.val = 1
        calculate_moves(node.left)
        calculate_moves(node.right)

    calculate_moves(root)
    return moves
